import React, { useState } from 'react';
import {
  Card,
  Icon,
  IconButton,
  Modal,
  Button,
  Badge,
  Spinner,
} from '@unlimit/ui';
import type { ReactNode } from 'react';

// ─── Types ───────────────────────────────────────────────────────────────────

export type CardBrand = 'visa' | 'mastercard' | 'amex';

export interface PaymentCardProps {
  /** Unique identifier for this card */
  id: string;
  /** Full or last-4 digits — component always masks to last 4 */
  last4: string;
  /** MM/YY expiry string, e.g. "12/26" */
  expiry: string;
  /** Cardholder name */
  cardholderName: string;
  /** Card network brand */
  brand: CardBrand;
  /** Whether this card is currently selected */
  isSelected?: boolean;
  /** Whether the card is expired / non-selectable */
  disabled?: boolean;
  /** Async selection in progress */
  isLoading?: boolean;
  /** Async deletion in progress */
  isDeleting?: boolean;
  /** Error message to surface (failed selection or load) */
  error?: string;
  /** Called when the user selects this card */
  onSelect?: (id: string) => void;
  /** Called when the user confirms deletion */
  onDelete?: (id: string) => Promise<void> | void;
}

// ─── Brand label map ─────────────────────────────────────────────────────────

const BRAND_LABELS: Record<CardBrand, string> = {
  visa: 'Visa',
  mastercard: 'Mastercard',
  amex: 'American Express',
};

// ─── Component ───────────────────────────────────────────────────────────────

export const PaymentCard: React.FC<PaymentCardProps> = ({
  id,
  last4,
  expiry,
  cardholderName,
  brand,
  isSelected = false,
  disabled = false,
  isLoading = false,
  isDeleting = false,
  error,
  onSelect,
  onDelete,
}) => {
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [deleteError, setDeleteError] = useState<string | null>(null);
  const [localDeleting, setLocalDeleting] = useState(false);

  const effectiveDeleting = isDeleting || localDeleting;
  const brandLabel = BRAND_LABELS[brand];

  // ── Handlers ──────────────────────────────────────────────────────────────

  const handleSelect = () => {
    if (disabled || effectiveDeleting || isLoading) return;
    onSelect?.(id);
  };

  const handleDeleteClick = (e: React.MouseEvent | React.KeyboardEvent) => {
    // Prevent the card's onClick (select) from firing
    e.stopPropagation();
    setDeleteError(null);
    setIsDeleteModalOpen(true);
  };

  const handleModalClose = () => {
    if (localDeleting) return; // block close while in-flight
    setIsDeleteModalOpen(false);
    setDeleteError(null);
  };

  const handleConfirmDelete = async () => {
    setDeleteError(null);
    setLocalDeleting(true);
    try {
      await onDelete?.(id);
      setIsDeleteModalOpen(false);
    } catch {
      setDeleteError('Failed to delete card. Please try again.');
    } finally {
      setLocalDeleting(false);
    }
  };

  // ── Derived display values ─────────────────────────────────────────────────

  const maskedDisplay = `•••• •••• •••• ${last4}`;
  const cardAriaLabel = `${brandLabel} card ending in ${last4}`;
  const deleteAriaLabel = `Delete card ending in ${last4}`;
  const expiryAriaLabel = `Expires ${expiry}`;

  // ── Loading / deleting overlay ────────────────────────────────────────────

  if (effectiveDeleting) {
    return (
      <>
        <div className="payment-card payment-card--deleting" aria-busy="true">
          <Card padding="md">
            <div className="payment-card__overlay" role="status" aria-label={`Deleting card ending in ${last4}`}>
              <Spinner size="sm" label={`Deleting card ending in ${last4}`} />
              <span className="payment-card__overlay-text" aria-hidden="true">
                Deleting…
              </span>
            </div>
          </Card>
        </div>

        {/* Keep modal mounted so focus isn't lost mid-flight */}
        <Modal
          open={isDeleteModalOpen}
          onClose={handleModalClose}
          title="Delete card"
        >
          <ModalContent
            last4={last4}
            isDeleting={localDeleting}
            deleteError={deleteError}
            onConfirm={handleConfirmDelete}
            onCancel={handleModalClose}
          />
        </Modal>
      </>
    );
  }

  if (isLoading) {
    return (
      <div className="payment-card payment-card--loading" aria-busy="true">
        <Card padding="md">
          <div className="payment-card__overlay" role="status" aria-label={`Loading card ending in ${last4}`}>
            <Spinner size="sm" label={`Loading card ending in ${last4}`} />
          </div>
        </Card>
      </div>
    );
  }

  // ── Main render ───────────────────────────────────────────────────────────

  return (
    <>
      <div
        className={[
          'payment-card',
          isSelected ? 'payment-card--selected' : '',
          disabled ? 'payment-card--disabled' : '',
          error ? 'payment-card--error' : '',
        ]
          .filter(Boolean)
          .join(' ')}
      >
        <Card
          padding="md"
          interactive={!disabled}
          selected={isSelected}
          onClick={!disabled ? handleSelect : undefined}
        >
          <div className="payment-card__inner">
            {/* ── Top row: brand icon + badge + delete ── */}
            <div className="payment-card__top-row">
              <div className="payment-card__brand">
                <Icon
                  name={brand}
                  size="lg"
                  aria-hidden={true}
                />
                <span className="payment-card__brand-label">{brandLabel}</span>
              </div>

              <div className="payment-card__actions">
                {disabled && (
                  <Badge variant="danger">Expired</Badge>
                )}
                {/* Stop propagation so delete click doesn't trigger card select */}
                <div
                  onClick={(e) => e.stopPropagation()}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') e.stopPropagation();
                  }}
                  className="payment-card__delete-wrapper"
                >
                  <IconButton
                    variant="destructive"
                    size="md"
                    icon={<Icon name="trash" aria-hidden={true} />}
                    aria-label={deleteAriaLabel}
                    onClick={handleDeleteClick as () => void}
                    disabled={effectiveDeleting}
                  />
                </div>
              </div>
            </div>

            {/* ── Card number ── */}
            <div
              className="payment-card__number"
              aria-label={cardAriaLabel}
            >
              <span aria-hidden="true">{maskedDisplay}</span>
            </div>

            {/* ── Bottom row: cardholder + expiry ── */}
            <div className="payment-card__bottom-row">
              <div className="payment-card__cardholder">
                <span className="payment-card__meta-label">Cardholder</span>
                <span className="payment-card__meta-value">{cardholderName}</span>
              </div>
              <div className="payment-card__expiry">
                <span className="payment-card__meta-label">Expires</span>
                <span
                  className="payment-card__meta-value"
                  aria-label={expiryAriaLabel}
                >
                  {expiry}
                </span>
              </div>
            </div>

            {/* ── Error message ── */}
            {error && (
              <div
                className="payment-card__error"
                role="alert"
                aria-live="assertive"
              >
                <Icon name="alert" size="sm" aria-hidden={true} />
                <span>{error}</span>
              </div>
            )}
          </div>
        </Card>
      </div>

      {/* ── Delete confirmation modal ── */}
      <Modal
        open={isDeleteModalOpen}
        onClose={handleModalClose}
        title="Delete card"
      >
        <ModalContent
          last4={last4}
          isDeleting={localDeleting}
          deleteError={deleteError}
          onConfirm={handleConfirmDelete}
          onCancel={handleModalClose}
        />
      </Modal>
    </>
  );
};

// ─── Modal content (extracted to keep JSX readable) ───────────────────────────

interface ModalContentProps {
  last4: string;
  isDeleting: boolean;
  deleteError: string | null;
  onConfirm: () => void;
  onCancel: () => void;
}

const ModalContent: React.FC<ModalContentProps> = ({
  last4,
  isDeleting,
  deleteError,
  onConfirm,
  onCancel,
}) => (
  <div className="payment-card__modal-body">
    <p className="payment-card__modal-description">
      Are you sure you want to remove the card ending in{' '}
      <strong>{last4}</strong>? This action cannot be undone.
    </p>

    {deleteError && (
      <div
        className="payment-card__modal-error"
        role="alert"
        aria-live="assertive"
      >
        <Icon name="alert" size="sm" aria-hidden={true} />
        <span>{deleteError}</span>
      </div>
    )}

    <div className="payment-card__modal-actions">
      <Button
        variant="secondary"
        onClick={onCancel}
        disabled={isDeleting}
      >
        Cancel
      </Button>
      <Button
        variant="destructive"
        loading={isDeleting}
        onClick={onConfirm}
      >
        Delete card
      </Button>
    </div>
  </div>
);

export default PaymentCard;

/* ─── PaymentCard styles ──────────────────────────────────────────────────── */

.payment-card {
  font-family: var(--font-family-sans);
  position: relative;
  /* Ensure focus ring is never clipped */
  overflow: visible;
}

/* ── Inner layout ─────────────────────────────────────────────────────────── */

.payment-card__inner {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-4);
  min-width: 0; /* allow text truncation */
}

/* ── Top row ──────────────────────────────────────────────────────────────── */

.payment-card__top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-2);
}

.payment-card__brand {
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
}

.payment-card__brand-label {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  color: var(--color-neutral-600);
  line-height: var(--line-height-tight);
}

.payment-card__actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
  /* Shrink-proof so badge + button never wrap awkwardly */
  flex-shrink: 0;
}

/* Ensure delete button touch target >= 44×44 px on mobile */
.payment-card__delete-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
}

/* ── Card number ──────────────────────────────────────────────────────────── */

.payment-card__number {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-medium);
  color: var(--color-neutral-900);
  letter-spacing: 0.12em;
  line-height: var(--line-height-tight);
  /* Prevent overflow on narrow viewports */
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── Bottom row ───────────────────────────────────────────────────────────── */

.payment-card__bottom-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--spacing-4);
  flex-wrap: wrap;
}

.payment-card__cardholder,
.payment-card__expiry {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-1);
  min-width: 0;
}

.payment-card__meta-label {
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-regular);
  color: var(--color-muted-foreground);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  line-height: var(--line-height-tight);
}

.payment-card__meta-value {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  color: var(--color-foreground);
  line-height: var(--line-height-tight);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── Error banner ─────────────────────────────────────────────────────────── */

.payment-card__error {
  display: flex;
  align-items: center;
  gap: var(--spacing-2);
  padding: var(--spacing-2) var(--spacing-3);
  background-color: color-mix(in srgb, var(--color-danger) 10%, transparent);
  border: 1px solid var(--color-danger);
  border-radius: var(--radius-sm);
  color: var(--color-danger);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  line-height: var(--line-height-normal);
}

/* ── Overlay (loading / deleting) ─────────────────────────────────────────── */

.payment-card__overlay {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-3);
  min-height: 96px;
}

.payment-card__overlay-text {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  color: var(--color-muted-foreground);
}

/* ── Disabled state ───────────────────────────────────────────────────────── */

.payment-card--disabled .payment-card__number,
.payment-card--disabled .payment-card__meta-value {
  color: var(--color-neutral-400);
}

.payment-card--disabled .payment-card__brand-label {
  color: var(--color-neutral-400);
}

/* ── Error state (card-level) ─────────────────────────────────────────────── */

.payment-card--error > * {
  border-color: var(--color-danger) !important;
}

/* ── Hover state ──────────────────────────────────────────────────────────── */
/* Applied to the Card's inner button when interactive=true */
.payment-card:not(.payment-card--disabled):not(.payment-card--deleting):not(.payment-card--loading) button[class*='card']:hover,
.payment-card:not(.payment-card--disabled):not(.payment-card--deleting):not(.payment-card--loading) [role='button']:hover {
  background-color: var(--color-neutral-100);
  box-shadow: var(--shadow-md);
  transition: background-color 150ms ease, box-shadow 150ms ease;
}

/* ── Focus-visible state ──────────────────────────────────────────────────── */
.payment-card button[class*='card']:focus-visible,
.payment-card [role='button']:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: 2px;
  border-radius: var(--radius-md);
}

/* ── Selected state ───────────────────────────────────────────────────────── */
.payment-card--selected button[class*='card'],
.payment-card--selected [role='button'] {
  border-color: var(--color-brand-primary) !important;
  box-shadow: 0 0 0 2px var(--color-brand-primary);
  background-color: color-mix(in srgb, var(--color-brand-primary) 6%, var(--color-neutral-0));
}

/* ── Responsive: narrow viewports (< 375px) ──────────────────────────────── */

@media (max-width: 374px) {
  .payment-card__number {
    font-size: var(--font-size-base);
    letter-spacing: 0.08em;
  }

  .payment-card__bottom-row {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-2);
  }

  .payment-card__top-row {
    flex-wrap: wrap;
  }
}

import React, { useState } from 'react';
import { PaymentCard } from './PaymentCard';

export default {
  title: 'Fintech/PaymentCard',
  component: PaymentCard,
};

// ── Helpers ──────────────────────────────────────────────────────────────────

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

// ── Stories ──────────────────────────────────────────────────────────────────

export const Default = () => (
  <div style={{ maxWidth: 380 }}>
    <PaymentCard
      id="card-1"
      last4="4242"
      expiry="12/26"
      cardholderName="Jane Doe"
      brand="visa"
    />
  </div>
);

export const Selected = () => (
  <div style={{ maxWidth: 380 }}>
    <PaymentCard
      id="card-2"
      last4="5555"
      expiry="08/25"
      cardholderName="John Smith"
      brand="mastercard"
      isSelected
    />
  </div>
);

export const Disabled_Expired = () => (
  <div style={{ maxWidth: 380 }}>
    <PaymentCard
      id="card-3"
      last4="3782"
      expiry="01/23"
      cardholderName="Alice Johnson"
      brand="amex"
      disabled
    />
  </div>
);

export const Loading = () => (
  <div style={{ maxWidth: 380 }}>
    <PaymentCard
      id="card-4"
      last4="4242"
      expiry="12/26"
      cardholderName="Jane Doe"
      brand="visa"
      isLoading
    />
  </div>
);

export const Deleting = () => (
  <div style={{ maxWidth: 380 }}>
    <PaymentCard
      id="card-5"
      last4="4242"
      expiry="12/26"
      cardholderName="Jane Doe"
      brand="visa"
      isDeleting
    />
  </div>
);

export const WithError = () => (
  <div style={{ maxWidth: 380 }}>
    <PaymentCard
      id="card-6"
      last4="4242"
      expiry="12/26"
      cardholderName="Jane Doe"
      brand="visa"
      error="Failed to load card details. Please refresh."
    />
  </div>
);

export const Interactive = () => {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [cards, setCards] = useState([
    { id: 'c1', last4: '4242', expiry: '12/26', name: 'Jane Doe', brand: 'visa' as const },
    { id: 'c2', last4: '5555', expiry: '08/25', name: 'John Smith', brand: 'mastercard' as const },
    { id: 'c3', last4: '3782', expiry: '01/23', name: 'Alice Johnson', brand: 'amex' as const, expired: true },
  ]);

  const handleDelete = async (id: string) => {
    await sleep(1500);
    setCards((prev) => prev.filter((c) => c.id !== id));
    if (selectedId === id) setSelectedId(null);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16, maxWidth: 380 }}>
      {cards.map((card) => (
        <PaymentCard
          key={card.id}
          id={card.id}
          last4={card.last4}
          expiry={card.expiry}
          cardholderName={card.name}
          brand={card.brand}
          isSelected={selectedId === card.id}
          disabled={'expired' in card && card.expired}
          onSelect={setSelectedId}
          onDelete={handleDelete}
        />
      ))}
    </div>
  );
};
